<?php
namespace App\Http\Controllers\Tenant\Admin;use App\Http\Controllers\Controller;use App\Models\Customer\Contact;use App\Models\Inbox\Conversation;use App\Models\Knowledge\KnowledgeFaq;use App\Models\Ticket\Ticket;use Illuminate\Http\Request;use Inertia\Inertia;use Inertia\Response;
class SearchController extends Controller{public function __invoke(Request $r):Response{abort_unless($r->user('tenant')->can('customers.view')||$r->user('tenant')->can('inbox.view'),403);$q=trim((string)$r->query('q'));abort_if(mb_strlen($q)>255,422);return Inertia::render('Tenant/Admin/Search/Index',['query'=>$q,'contacts'=>$q?Contact::where(fn($x)=>$x->where('display_name','like',"%{$q}%")->orWhere('email','like',"%{$q}%")->orWhere('phone','like',"%{$q}%"))->limit(20)->get(['public_uuid','display_name','email']):[],'conversations'=>$q?Conversation::where('subject','like',"%{$q}%")->limit(20)->get(['public_uuid','subject','status']):[],'tickets'=>$q?Ticket::where(fn($x)=>$x->where('subject','like',"%{$q}%")->orWhere('ticket_number','like',"%{$q}%"))->limit(20)->get(['public_uuid','ticket_number','subject']):[],'articles'=>$q?KnowledgeFaq::where('question','like',"%{$q}%")->where('status','published')->limit(20)->get(['uuid','question']):[]]);}}
